package com.sunrise.dentalclinic.exception;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.*;
@ControllerAdvice public class GlobalExceptionHandler{
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> invalid(MethodArgumentNotValidException e){var fields=new LinkedHashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(x->fields.putIfAbsent(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"error","Validation failed","fields",fields));}
 @ExceptionHandler(ResourceNotFoundException.class) Object missing(ResourceNotFoundException e,HttpServletRequest r){return response(e,r,HttpStatus.NOT_FOUND);}@ExceptionHandler(BusinessException.class)Object business(BusinessException e,HttpServletRequest r){return response(e,r,HttpStatus.CONFLICT);}
 private Object response(RuntimeException e,HttpServletRequest r,HttpStatus s){if(r.getRequestURI().startsWith("/api/"))return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s.value(),"error",e.getMessage()));return new org.springframework.web.servlet.ModelAndView("error/friendly",Map.of("message",e.getMessage(),"status",s.value()),s);}}
